resource "google_container_node_pool" "app" {
  name       = "app-pool"
  cluster    = google_container_cluster.app.name
  location   = var.region
  node_count = 3

  node_config {
    machine_type = "e2-standard-4"

    oauth_scopes = [
      "https://www.googleapis.com/auth/cloud-platform"
    ]
  }
}

